package terraform

import (
	"strings"
	"testing"

	"github.com/hashicorp/terraform/internal/addrs"
	"github.com/hashicorp/terraform/internal/providers"
)

func TestTmpIssueRepro(t *testing.T) {
	m := testModuleInline(t, map[string]string{
		"main.tf": `
resource "null_resource" "undef-local" {
}

resource "null_resource" "undef-var" {
}

import {
  to = null_resource.undef-local
  id = local.something_not_defined
}

import {
  to = null_resource.undef-var
  id = var.some_other_undefined_thing
}

import {
    to = null_resource.not-a-real-resource
    id = "blah"
}
`,
	})

	p := testProvider("null")
	ctx := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			addrs.NewDefaultProvider("null"): testProviderFuncFixed(p),
		},
	})

	diags := ctx.Validate(m, nil)
	if !diags.HasErrors() {
		t.Fatal("succeeded; want errors")
	}
	got := diags.Err().Error()
	t.Logf("diags:\n%s", got)
	for _, want := range []string{
		"something_not_defined",
		"some_other_undefined_thing",
	} {
		if !strings.Contains(got, want) {
			t.Fatalf("missing %q in:\n%s", want, got)
		}
	}
}

func TestTmpIssueReproValid(t *testing.T) {
	m := testModuleInline(t, map[string]string{
		"main.tf": `
locals {
  id = "foo"
}
variable "v" {
  type = string
}
resource "null_resource" "ok" {
}

import {
  to = null_resource.ok
  id = local.id
}

import {
  to = null_resource.ok2
  id = var.v
}
`,
	})

	p := testProvider("null")
	ctx := testContext2(t, &ContextOpts{
		Providers: map[addrs.Provider]providers.Factory{
			addrs.NewDefaultProvider("null"): testProviderFuncFixed(p),
		},
	})

	diags := ctx.Validate(m, nil)
	if diags.HasErrors() {
		t.Fatalf("unexpected errors: %s", diags.Err().Error())
	}
}

